SELECT * FROM (SELECT e.event_id,'TOP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Leveling Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='L')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'TOP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Heat Treatment Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='A')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'TOP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'TOP:'||operation_id event_id,'Surface Finishing Completed' activity,finished_at timestamp,operation_id source_key FROM finishing_operation_history WHERE finished_at IS NOT NULL AND (operation_code='S')) e JOIN finishing_operation_history s ON s.operation_id=e.source_key) ORDER BY case_id,timestamp,event_id;
